def lp_sum(model,texts,plens,bs=16):
    S=[]
    for i in range(0,len(texts),bs):
        e=tok(texts[i:i+bs],return_tensors="pt",padding=True,truncation=True,max_length=320,add_special_tokens=False); e={k:v.to(DEV) for k,v in e.items()}
