def _jctx(u):
    """Judge context: a chat prompt with system attached.  It must differ from the policy context or the reward is not 0."""
    if XJ:                                                   # zz_xj: judge template (only user if system is empty)
        _m=([{"role":"system","content":JSYS}] if JSYS else [])+[{"role":"user","content":u}]
        return jtok.apply_chat_template(_m,tokenize=False,add_generation_prompt=True,enable_thinking=False)
    return tok.apply_chat_template(
        [{"role":"system","content":JSYS},{"role":"user","content":u}],
        tokenize=False,add_generation_prompt=True,enable_thinking=False)
def _jtexts(own,RESP,QL):
    """(prompt+candidate) to be scored by the judge, and the prompt lengths.  Built separately from the policy side's T,P."""
    TT=[];PP=[]
    cache={}
    for i in range(len(RESP)):
        qi=int(own[i])
        if qi not in cache:
            p=_jctx(QL[qi]); cache[qi]=(p,len((jtok if XJ else tok)(p,add_special_tokens=False).input_ids))
        p,pl=cache[qi]
        TT.append(p+RESP[i]); PP.append(pl)
    return TT,PP
