def st_dtypes(d):
    """Set of stored dtypes in the safetensors header (judged from the header, not the config)."""
    import struct,glob
    out={}
    for f in sorted(glob.glob(os.path.join(d,"*.safetensors"))):
        with open(f,"rb") as fh:
            n=struct.unpack("<Q",fh.read(8))[0]; H=json.loads(fh.read(n))
        for k,v in H.items():
            if k!="__metadata__": out[v["dtype"]]=out.get(v["dtype"],0)+1
    return out
def load_fp32(path):
    m=AutoModelForCausalLM.from_pretrained(path,dtype=torch.float32).to(DEV).eval()
    assert all(p.dtype==torch.float32 for p in m.parameters()),"fp32 is not parameters"
    for p in m.parameters(): p.requires_grad_(False)
    return m
def md5f(p): return hashlib.md5(open(p,"rb").read()).hexdigest()
